#!/usr/bin/env bash
# Generated by scripts/build-cdx.sh; edit bin/cdx.d/* and rebuild.
set -euo pipefail

# Fancy-ish log strings
CODEX_TERM_IS_DUMB=0
if [[ "${TERM:-}" == "dumb" ]]; then
  CODEX_TERM_IS_DUMB=1
fi

CODEX_COLOR_ENABLED=0
if [[ -t 1 ]] && [[ -z "${NO_COLOR:-}" ]] && (( ! CODEX_TERM_IS_DUMB )); then
  CODEX_COLOR_ENABLED=1
fi

if (( CODEX_COLOR_ENABLED )); then
  BOLD="\033[1m"
  DIM="\033[2m"
  GREEN="\033[32m"
  YELLOW="\033[33m"
  ORANGE="\033[38;5;208m"
  CYAN="\033[96m"
  BLUE="\033[36m"
  MAGENTA="\033[35m"
  RED="\033[31m"
  RESET="\033[0m"
else
  BOLD=""
  DIM=""
  GREEN=""
  YELLOW=""
  ORANGE=""
  CYAN=""
  BLUE=""
  MAGENTA=""
  RED=""
  RESET=""
fi

if (( CODEX_TERM_IS_DUMB )); then
  LOG_PREFIX_INFO="${LOG_PREFIX_INFO:->}"
else
  LOG_PREFIX_INFO="${LOG_PREFIX_INFO:-»}"
fi
LOG_PREFIX_WARN="${LOG_PREFIX_WARN:-!}"
LOG_PREFIX_ERROR="${LOG_PREFIX_ERROR:-x}"

log_info() {
  (( CODEX_SILENT )) && return
  local msg="${1-}"
  while IFS= read -r line; do
    printf "%b%s%b %s\n" "${BLUE}${BOLD}" "$LOG_PREFIX_INFO" "${RESET}" "$line"
  done <<< "$msg"
}

log_warn() {
  (( CODEX_SILENT )) && return
  local msg="${1-}"
  while IFS= read -r line; do
    printf "%b%s%b %s\n" "${YELLOW}${BOLD}" "$LOG_PREFIX_WARN" "${RESET}" "$line" >&2
  done <<< "$msg"
}

log_error() {
  local msg="${1-}"
  while IFS= read -r line; do
    printf "%b%s%b %s\n" "${RED}${BOLD}" "$LOG_PREFIX_ERROR" "${RESET}" "$line" >&2
  done <<< "$msg"
}

log_debug() {
  (( CODEX_SILENT )) && return 0
  (( CODEX_DEBUG )) && printf "%b[debug]%b %s\n" "${DIM}" "${RESET}" "$1" >&2
  return 0
}

lowercase() {
  local input="${1-}"
  printf '%s' "$input" | tr '[:upper:]' '[:lower:]'
}

SED_ERE_FLAG=""
detect_sed_ere_flag() {
  if [[ -n "$SED_ERE_FLAG" ]]; then
    return 0
  fi
  if echo x | sed -r 's/x/x/' >/dev/null 2>&1; then
    SED_ERE_FLAG="-r"
  else
    SED_ERE_FLAG="-E"
  fi
}

strip_ansi_sgr() {
  local text="${1-}"
  detect_sed_ere_flag
  sed "$SED_ERE_FLAG" 's/\x1B\[[0-9;]*[mK]//g' <<<"$text"
}

sha256_file() {
  local target="${1-}"
  [[ -n "$target" ]] || return 1
  [[ -f "$target" ]] || return 1

  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$target" | awk '{print $1}'
    return 0
  fi
  if command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$target" | awk '{print $1}'
    return 0
  fi
  if command -v openssl >/dev/null 2>&1; then
    openssl dgst -sha256 "$target" | awk '{print $NF}'
    return 0
  fi
  if command -v python3 >/dev/null 2>&1; then
    python3 - "$target" <<'PY'
import hashlib, pathlib, sys
print(hashlib.sha256(pathlib.Path(sys.argv[1]).read_bytes()).hexdigest())
PY
    return 0
  fi

  return 1
}

CODEX_PY_HTTP_UTIL="$(cat <<'PY'
import json
import os
import socket
import ssl
import urllib.error
import urllib.request

def cdx_enable_force_ipv4():
    if getattr(cdx_enable_force_ipv4, "_patched", False):
        return
    if os.environ.get("CODEX_FORCE_IPV4", "").lower() in ("1", "true", "yes"):
        _orig_getaddrinfo = socket.getaddrinfo
        def _force_getaddrinfo(host, port, family=0, type=0, proto=0, flags=0):
            return _orig_getaddrinfo(host, port, socket.AF_INET, type, proto, flags)
        socket.getaddrinfo = _force_getaddrinfo
    cdx_enable_force_ipv4._patched = True

def cdx_build_ssl_contexts(cafile="", allow_insecure_env="CODEX_SYNC_ALLOW_INSECURE"):
    contexts = []
    primary = ssl.create_default_context()
    if cafile:
        try:
            primary.load_verify_locations(cafile)
        except Exception:
            primary = None
    if primary is not None:
        try:
            primary.verify_flags &= ~ssl.VERIFY_X509_STRICT
        except AttributeError:
            pass
        contexts.append(primary)
    try:
        fallback = ssl.create_default_context()
        fallback.verify_flags &= ~ssl.VERIFY_X509_STRICT
        contexts.append(fallback)
    except Exception:
        pass
    allow_insecure = os.environ.get(allow_insecure_env, "").lower() in ("1", "true", "yes")
    if allow_insecure:
        try:
            contexts.append(ssl._create_unverified_context())
        except Exception:
            pass
    return contexts or [None]

def cdx_request_json(method, url, api_key, cafile="", payload=None, timeout=20, allow_insecure_env="CODEX_SYNC_ALLOW_INSECURE"):
    data = None
    headers = {"X-API-Key": api_key}
    if payload is not None:
        data = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        headers["Content-Type"] = "application/json"
    try:
        req = urllib.request.Request(url, data=data, headers=headers, method=method)
    except Exception as exc:
        raise RuntimeError(f"request failed: {exc}") from exc
    last_err = None
    for ctx in cdx_build_ssl_contexts(cafile, allow_insecure_env=allow_insecure_env):
        try:
            with urllib.request.urlopen(req, timeout=timeout, context=ctx) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as exc:
            body = exc.read().decode("utf-8", "ignore")
            reason = f"http-{exc.code}"
            if body:
                reason = f"{reason}:{body.strip()[:80]}"
            raise RuntimeError(reason) from exc
        except Exception as exc:
            last_err = exc
            continue
    raise RuntimeError(f"request failed: {last_err}")
PY
)"
export CODEX_PY_HTTP_UTIL

CODEX_PY_IPV4_PROXY_UTIL="$(cat <<'PY'
import os
import select
import signal
import socket
import socketserver
import sys
from urllib.parse import urlsplit


def _connect_ipv4(host, port):
    last_err = None
    for family, socktype, proto, _canonname, sockaddr in socket.getaddrinfo(
        host, port, socket.AF_INET, socket.SOCK_STREAM
    ):
        sock = None
        try:
            sock = socket.socket(family, socktype, proto)
            sock.settimeout(15.0)
            sock.connect(sockaddr)
            sock.settimeout(None)
            return sock
        except OSError as exc:
            last_err = exc
            if sock is not None:
                try:
                    sock.close()
                except OSError:
                    pass
    if last_err is None:
        raise OSError(f"failed to resolve domain to IPv4 addresses: {host}")
    raise last_err


def _relay_bidirectional(left, right):
    sockets = [left, right]
    try:
        for sock in sockets:
            sock.setblocking(False)
        while True:
            readable, _, _ = select.select(sockets, [], [], 60.0)
            if not readable:
                continue
            for source in readable:
                target = right if source is left else left
                try:
                    chunk = source.recv(65536)
                except OSError:
                    return
                if not chunk:
                    return
                view = memoryview(chunk)
                while view:
                    try:
                        written = target.send(view)
                    except OSError:
                        return
                    view = view[written:]
    finally:
        for sock in sockets:
            try:
                sock.close()
            except OSError:
                pass


class ThreadedTcpServer(socketserver.ThreadingMixIn, socketserver.TCPServer):
    allow_reuse_address = True
    daemon_threads = True


class ProxyHandler(socketserver.StreamRequestHandler):
    def handle(self):
        request_line = self.rfile.readline(65537)
        if not request_line:
            return
        if len(request_line) > 65536:
            self._write_error(414, b"request line too long")
            return
        try:
            method, target, version = request_line.decode("iso-8859-1").strip().split(" ", 2)
        except ValueError:
            self._write_error(400, b"bad request")
            return

        headers = []
        while True:
            line = self.rfile.readline(65537)
            if not line:
                return
            if len(line) > 65536:
                self._write_error(431, b"header line too long")
                return
            if line in (b"\r\n", b"\n"):
                break
            headers.append(line)

        if method.upper() == "CONNECT":
            self._handle_connect(target)
            return

        self._handle_forward(method, target, version, headers)

    def _handle_connect(self, target):
        if ":" not in target:
            self._write_error(400, b"CONNECT target missing port")
            return
        host, port_text = target.rsplit(":", 1)
        try:
            port = int(port_text)
        except ValueError:
            self._write_error(400, b"invalid CONNECT port")
            return
        try:
            upstream = _connect_ipv4(host, port)
        except OSError as exc:
            self._write_error(502, f"upstream connect failed: {exc}".encode("utf-8", "ignore"))
            return
        self.wfile.write(b"HTTP/1.1 200 Connection established\r\n\r\n")
        self.wfile.flush()
        _relay_bidirectional(self.connection, upstream)

    def _handle_forward(self, method, target, version, headers):
        parts = urlsplit(target)
        host = parts.hostname
        if not host:
            self._write_error(400, b"proxy request requires absolute URL")
            return
        scheme = (parts.scheme or "http").lower()
        port = parts.port or (443 if scheme == "https" else 80)
        path = parts.path or "/"
        if parts.query:
            path += "?" + parts.query

        content_length = 0
        sanitized_headers = []
        saw_host = False
        for raw_header in headers:
            lowered = raw_header.lower()
            if lowered.startswith(b"proxy-connection:"):
                continue
            if lowered.startswith(b"host:"):
                saw_host = True
            if lowered.startswith(b"content-length:"):
                try:
                    content_length = int(raw_header.split(b":", 1)[1].strip() or b"0")
                except ValueError:
                    content_length = 0
            sanitized_headers.append(raw_header)
        if not saw_host:
            host_value = host if parts.port is None else f"{host}:{port}"
            sanitized_headers.append(f"Host: {host_value}\r\n".encode("iso-8859-1"))

        body = b""
        if content_length > 0:
            body = self.rfile.read(content_length)

        try:
            upstream = _connect_ipv4(host, port)
        except OSError as exc:
            self._write_error(502, f"upstream connect failed: {exc}".encode("utf-8", "ignore"))
            return

        try:
            upstream.sendall(f"{method} {path} {version}\r\n".encode("iso-8859-1"))
            for raw_header in sanitized_headers:
                upstream.sendall(raw_header)
            upstream.sendall(b"\r\n")
            if body:
                upstream.sendall(body)
            _relay_bidirectional(self.connection, upstream)
        except OSError:
            try:
                upstream.close()
            except OSError:
                pass

    def _write_error(self, code, message):
        reason = {
            400: b"Bad Request",
            414: b"URI Too Long",
            431: b"Request Header Fields Too Large",
            502: b"Bad Gateway",
        }.get(code, b"Proxy Error")
        body = message + b"\n"
        self.wfile.write(
            b"HTTP/1.1 %d %s\r\nContent-Length: %d\r\nConnection: close\r\n\r\n%s"
            % (code, reason, len(body), body)
        )
        self.wfile.flush()


def main():
    state_dir = os.environ.get("CODEX_IPV4_PROXY_DIR", "")
    if not state_dir:
        print("missing CODEX_IPV4_PROXY_DIR", file=sys.stderr)
        return 1
    os.makedirs(state_dir, exist_ok=True)
    port_file = os.path.join(state_dir, "port")

    server = ThreadedTcpServer(("127.0.0.1", 0), ProxyHandler)
    with open(port_file, "w", encoding="utf-8") as handle:
        handle.write(str(server.server_address[1]))
        handle.flush()

    def _shutdown(_signum, _frame):
        server.shutdown()

    signal.signal(signal.SIGTERM, _shutdown)
    signal.signal(signal.SIGINT, _shutdown)

    try:
        server.serve_forever(poll_interval=0.5)
    finally:
        server.server_close()

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
PY
)"
export CODEX_PY_IPV4_PROXY_UTIL

