sanitize_lock_token() {
  local token="${1-}"
  token="${token//$'\r'/}"
  token="${token//$'\n'/}"
  token="$(printf '%s' "$token" | tr -c '[:alnum:]._-' '_')"
  token="${token#_}"
  token="${token%_}"
  if [[ -z "$token" ]]; then
    token="default"
  fi
  printf '%s' "$token"
}

compute_run_lock_scope_key() {
  local base_scope=""
  local installation="${CODEX_INSTALLATION_ID:-}"
  if [[ -n "$installation" ]]; then
    base_scope="$(sanitize_lock_token "$installation")"
  else
    local raw="${CODEX_SYNC_BASE_URL_DEFAULT:-${CODEX_SYNC_BASE_URL:-}}|${CODEX_SYNC_FQDN:-none}"
    local digest=""
    if command -v sha256sum >/dev/null 2>&1; then
      digest="$(printf '%s' "$raw" | sha256sum | awk '{print $1}')"
    elif command -v shasum >/dev/null 2>&1; then
      digest="$(printf '%s' "$raw" | shasum -a 256 | awk '{print $1}')"
    elif command -v cksum >/dev/null 2>&1; then
      digest="$(printf '%s' "$raw" | cksum | awk '{print $1}')"
    else
      digest="$raw"
    fi
    digest="${digest:0:16}"
    base_scope="$(sanitize_lock_token "scope-${digest}")"
  fi

  local uid=""
  uid="$(id -u 2>/dev/null || true)"
  local user_scope=""
  if [[ "$uid" =~ ^[0-9]+$ ]]; then
    user_scope="u${uid}"
  else
    user_scope="user-$(sanitize_lock_token "$CURRENT_USER")"
  fi
  printf '%s' "$(sanitize_lock_token "${base_scope}-${user_scope}")"
}

select_run_lock_dir() {
  # Use shared temp locations; lock scope is per-user to avoid cross-user lock collisions.
  local candidates=("/tmp" "/var/tmp")
  local dir=""
  for dir in "${candidates[@]}"; do
    if [[ -d "$dir" && -w "$dir" ]]; then
      printf '%s' "$dir"
      return 0
    fi
  done
  return 1
}

close_run_lock_fd() {
  if [[ -n "${CDX_RUN_LOCK_FD:-}" ]]; then
    eval "exec ${CDX_RUN_LOCK_FD}>&-" 2>/dev/null || true
    CDX_RUN_LOCK_FD=""
  fi
}

write_run_lock_metadata() {
  if [[ -z "$CDX_RUN_LOCK_META_PATH" ]]; then
    return 1
  fi

  local started_at
  started_at="$(date -u +"%Y-%m-%dT%H:%M:%SZ" 2>/dev/null || true)"
  local argv_text=""
  if ! declare -p CODEX_ORIGINAL_ARGC >/dev/null 2>&1 || [[ ! "${CODEX_ORIGINAL_ARGC:-}" =~ ^[0-9]+$ ]]; then
    CODEX_ORIGINAL_ARGC=0
  fi
  if (( CODEX_ORIGINAL_ARGC > 0 )) && declare -p CODEX_ORIGINAL_ARGS >/dev/null 2>&1; then
    argv_text="$(printf '%q ' "${CODEX_ORIGINAL_ARGS[@]}")"
    argv_text="${argv_text% }"
  fi
  local tmp="${CDX_RUN_LOCK_META_PATH}.$$.$RANDOM.tmp"
  {
    printf 'pid=%s\n' "$$"
    printf 'user=%s\n' "$CURRENT_USER"
    printf 'host=%s\n' "$LOCAL_HOSTNAME"
    printf 'started_at=%s\n' "$started_at"
    printf 'wrapper=%s\n' "$WRAPPER_VERSION"
    printf 'argv=%s\n' "$argv_text"
  } >"$tmp" 2>/dev/null || return 1
  mv -f "$tmp" "$CDX_RUN_LOCK_META_PATH" 2>/dev/null || {
    rm -f "$tmp" 2>/dev/null || true
    return 1
  }
  return 0
}

read_run_lock_metadata_summary() {
  local pid=""
  local user=""
  local host=""
  local started_at=""
  if [[ ! -f "$CDX_RUN_LOCK_META_PATH" ]]; then
    return 1
  fi
  while IFS='=' read -r key value; do
    case "$key" in
      pid) pid="$value" ;;
      user) user="$value" ;;
      host) host="$value" ;;
      started_at) started_at="$value" ;;
    esac
  done <"$CDX_RUN_LOCK_META_PATH"

  local summary="active cdx run detected"
  local details=()
  [[ -n "$pid" ]] && details+=("pid ${pid}")
  [[ -n "$user" ]] && details+=("user ${user}")
  [[ -n "$host" ]] && details+=("host ${host}")
  [[ -n "$started_at" ]] && details+=("started ${started_at}")
  if (( ${#details[@]} > 0 )); then
    summary+=" (${details[*]})"
  fi
  printf '%s' "$summary"
  return 0
}

acquire_run_lock_or_mark_concurrent() {
  CDX_ACTIVE_RUN_DETECTED=0
  CDX_ACTIVE_RUN_INFO=""
  CDX_RUN_LOCK_HELD=0

  if (( CODEX_CONCURRENT_SYNC_OVERRIDE )); then
    return 0
  fi

  if ! command -v flock >/dev/null 2>&1; then
    log_warn "flock not available; concurrent-run guard disabled."
    return 0
  fi

  local lock_dir=""
  if ! lock_dir="$(select_run_lock_dir)"; then
    log_warn "No writable lock directory found; concurrent-run guard disabled."
    return 0
  fi
  CDX_RUN_LOCK_SCOPE_KEY="$(compute_run_lock_scope_key)"
  CDX_RUN_LOCK_PATH="${lock_dir}/cdx-run-${CDX_RUN_LOCK_SCOPE_KEY}.lock"
  CDX_RUN_LOCK_META_PATH="${lock_dir}/cdx-run-${CDX_RUN_LOCK_SCOPE_KEY}.meta"

  exec {CDX_RUN_LOCK_FD}>>"$CDX_RUN_LOCK_PATH" 2>/dev/null || {
    CDX_RUN_LOCK_FD=""
    log_warn "Cannot open run lock ${CDX_RUN_LOCK_PATH}; concurrent-run guard disabled."
    return 0
  }

  if flock -n "$CDX_RUN_LOCK_FD" 2>/dev/null; then
    CDX_RUN_LOCK_HELD=1
    write_run_lock_metadata || true
    return 0
  fi

  CDX_ACTIVE_RUN_DETECTED=1
  CDX_ACTIVE_RUN_INFO="$(read_run_lock_metadata_summary 2>/dev/null || true)"
  if [[ -z "$CDX_ACTIVE_RUN_INFO" ]]; then
    CDX_ACTIVE_RUN_INFO="active cdx run detected (lock ${CDX_RUN_LOCK_PATH})"
  fi
  close_run_lock_fd
  return 1
}

release_run_lock_if_held() {
  if (( CDX_RUN_LOCK_HELD )) && [[ -n "${CDX_RUN_LOCK_FD:-}" ]]; then
    flock -u "$CDX_RUN_LOCK_FD" 2>/dev/null || true
  fi
  close_run_lock_fd
  if (( CDX_RUN_LOCK_HELD )) && [[ -n "$CDX_RUN_LOCK_META_PATH" ]]; then
    rm -f "$CDX_RUN_LOCK_META_PATH" 2>/dev/null || true
  fi
  CDX_RUN_LOCK_HELD=0
}

config_has_profile() {
  local profile="${1-}"
  if [[ ! "$profile" =~ ^[A-Za-z0-9_-]+$ ]]; then
    return 1
  fi
  if [[ ! -f "$CONFIG_PATH" ]]; then
    return 1
  fi
  grep -qE "^[[:space:]]*\\[profiles\\.${profile}\\][[:space:]]*$" "$CONFIG_PATH"
}

config_profile_model() {
  local profile="${1-}"
  if [[ ! "$profile" =~ ^[A-Za-z0-9_-]+$ ]]; then
    return 1
  fi
  if [[ ! -f "$CONFIG_PATH" ]]; then
    return 1
  fi

  local profile_model=""
  profile_model="$(awk -v profile="$profile" '
    BEGIN { in_profile = 0 }
    /^[[:space:]]*\[/ {
      section = $0
      gsub(/^[[:space:]]*\[/, "", section)
      gsub(/\][[:space:]]*$/, "", section)
      in_profile = (section == ("profiles." profile))
      next
    }
    !in_profile { next }
    /^[[:space:]]*model[[:space:]]*=/ {
      line = $0
      sub(/^[[:space:]]*model[[:space:]]*=[[:space:]]*/, "", line)
      sub(/[[:space:]]*#.*/, "", line)
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", line)
      if (line ~ /^".*"$/) {
        sub(/^"/, "", line)
        sub(/"$/, "", line)
      }
      if (line != "") {
        print line
        exit 0
      }
    }
  ' "$CONFIG_PATH" 2>/dev/null || true)"
  if [[ -n "$profile_model" ]]; then
    printf '%s\n' "$profile_model"
    return 0
  fi
  return 1
}

config_default_model() {
  if [[ ! -f "$CONFIG_PATH" ]]; then
    return 1
  fi

  local default_model=""
  default_model="$(awk '
    BEGIN { in_root = 1 }
    /^[[:space:]]*\[/ {
      in_root = 0
      next
    }
    !in_root { next }
    /^[[:space:]]*model[[:space:]]*=/ {
      line = $0
      sub(/^[[:space:]]*model[[:space:]]*=[[:space:]]*/, "", line)
      sub(/[[:space:]]*#.*/, "", line)
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", line)
      if (line ~ /^".*"$/) {
        sub(/^"/, "", line)
        sub(/"$/, "", line)
      }
      if (line != "") {
        print line
        exit 0
      }
    }
  ' "$CONFIG_PATH" 2>/dev/null || true)"
  if [[ -n "$default_model" ]]; then
    printf '%s\n' "$default_model"
    return 0
  fi
  return 1
}

# Wrapper flags (strip before handing args to Codex)
if (( $# > 0 )); then
  parsed_args=()
  saw_double_dash=0
  for arg in "$@"; do
    if (( saw_double_dash )); then
      parsed_args+=("$arg")
      continue
    fi
    if [[ "$arg" == "--" ]]; then
      saw_double_dash=1
      parsed_args+=("$arg")
      continue
    fi
    if [[ "$arg" == "-4" ]]; then
      CODEX_FORCE_IPV4=1
      continue
    fi
    if [[ "$arg" == "--allow-concurrent-sync" ]]; then
      CODEX_CONCURRENT_SYNC_OVERRIDE=1
      continue
    fi
    parsed_args+=("$arg")
  done
  set -- "${parsed_args[@]}"
fi

# Convenience alias: `cdx ls` maps to the spark lane launcher.
if [[ "${1-}" == "ls" ]]; then
  shift
  set -- lane spark "$@"
fi

print_lane_usage() {
  cat >&2 <<'USAGE'
Usage:
  cdx lane
  cdx lane normal [--persist] [-- <codex args...>]
  cdx lane spark [--persist] [-- <codex args...>]
  cdx lane clear --persist [-- <codex args...>]
USAGE
}

is_reserved_codex_command() {
  local candidate="${1-}"
  case "$candidate" in
    exec|review|login|logout|mcp|mcp-server|app-server|completion|sandbox|debug|apply|resume|fork|cloud|features|help)
      return 0
      ;;
  esac
  return 1
}

is_help_flag() {
  local candidate="${1-}"
  [[ "$candidate" == "--help" || "$candidate" == "-h" ]]
}

is_codex_help_passthrough_invocation() {
  (( $# > 0 )) || return 1

  local first="${1-}"
  case "$first" in
    --help|-h|help)
      return 0
      ;;
  esac

  if ! is_reserved_codex_command "$first"; then
    return 1
  fi

  local arg
  for arg in "${@:2}"; do
    [[ "$arg" == "--" ]] && break
    if is_help_flag "$arg"; then
      return 0
    fi
  done

  return 1
}

if [[ "${1-}" == "lane" ]]; then
  CODEX_LANE_COMMAND=1
  CODEX_LANE_SHOW_ONLY=1
  CODEX_LANE_WANTS_RUN=0
  shift

  lane_passthrough=()
  lane_passthrough_mode=0
  while (( $# > 0 )); do
    if (( lane_passthrough_mode )); then
      lane_passthrough+=("$1")
      shift
      continue
    fi
    case "$1" in
      normal|spark)
        if [[ -n "$CODEX_LANE_TARGET" || "$CODEX_LANE_CLEAR_REQUEST" == "1" ]]; then
          print_lane_usage
          exit 1
        fi
        CODEX_LANE_TARGET="$1"
        CODEX_LANE_USER_SET=1
        CODEX_LANE_SHOW_ONLY=0
        CODEX_LANE_WANTS_RUN=1
        shift
        ;;
      clear)
        if [[ -n "$CODEX_LANE_TARGET" || "$CODEX_LANE_CLEAR_REQUEST" == "1" ]]; then
          print_lane_usage
          exit 1
        fi
        CODEX_LANE_CLEAR_REQUEST=1
        CODEX_LANE_SHOW_ONLY=1
        CODEX_LANE_WANTS_RUN=0
        shift
        ;;
      --persist)
        CODEX_LANE_PERSIST_REQUEST=1
        shift
        ;;
      --)
        lane_passthrough_mode=1
        shift
        ;;
      *)
        print_lane_usage
        printf 'Invalid lane argument: %s\n' "$1" >&2
        exit 1
        ;;
    esac
  done

  if (( CODEX_LANE_PERSIST_REQUEST )) && [[ -z "$CODEX_LANE_TARGET" && "$CODEX_LANE_CLEAR_REQUEST" != "1" ]]; then
    print_lane_usage
    printf 'cdx lane --persist requires a lane target or clear.\n' >&2
    exit 1
  fi

  if [[ "$CODEX_LANE_CLEAR_REQUEST" == "1" && "$CODEX_LANE_PERSIST_REQUEST" != "1" ]]; then
    print_lane_usage
    printf 'cdx lane clear requires --persist.\n' >&2
    exit 1
  fi

  if [[ -z "$CODEX_LANE_TARGET" && "$CODEX_LANE_CLEAR_REQUEST" != "1" ]] && (( ${#lane_passthrough[@]} > 0 )); then
    print_lane_usage
    printf 'cdx lane passthrough requires selecting normal or spark.\n' >&2
    exit 1
  fi

  if [[ "$CODEX_LANE_CLEAR_REQUEST" == "1" ]] && (( ${#lane_passthrough[@]} > 0 )); then
    print_lane_usage
    printf 'cdx lane clear does not support Codex passthrough arguments.\n' >&2
    exit 1
  fi

  if (( ${#lane_passthrough[@]} > 0 )); then
    CODEX_LANE_WANTS_RUN=1
  fi

  if (( ${#lane_passthrough[@]} > 0 )); then
    set -- "${lane_passthrough[@]}"
  else
    set --
  fi
fi

if [[ "${1-}" == "--execute" ]]; then
  shift
  if (( $# == 0 )); then
    printf 'Usage: cdx --execute "<prompt>" [codex args]\n' >&2
    exit 1
  fi
  prompt="$1"
  shift
  # Defer one-shot execution to the normal run path so auth/config sync still runs
  # (required for insecure hosts where auth.json is purged after each invocation).
  # Keep passthrough args first so explicit --model/--profile still win.
  set -- "$@" --sandbox read-only -a untrusted exec --skip-git-repo-check "$prompt"
fi

# Early one-shot commands
case "${1-}" in
  --wrapper-version|-W)
    printf 'cdx wrapper %s\n' "$WRAPPER_VERSION"
    exit 0
    ;;
  status|--status)
    CODEX_STATUS_ONLY=1
    shift
    ;;
  doctor|--doctor)
    CODEX_DOCTOR_ONLY=1
    shift
    ;;
  --uninstall)
    CODEX_DO_UNINSTALL=1
    shift
    ;;
  --update|-U)
    CODEX_FORCE_WRAPPER_UPDATE=1
    CODEX_EXIT_AFTER_UPDATE=1
    shift
    ;;
  --cron)
    CODEX_CRON_MODE=1
    CODEX_SILENT=1
    shift
    case "${1-}" in
      install) CODEX_CRON_INSTALL=1; shift ;;
      remove)  CODEX_CRON_REMOVE=1; shift ;;
    esac
    ;;
esac

case "${1-}" in
  --debug|--verbose)
    CODEX_DEBUG=1
    shift
    ;;
esac

case "${1-}" in
  status|--status)
    CODEX_STATUS_ONLY=1
    shift
    ;;
  doctor|--doctor)
    CODEX_DOCTOR_ONLY=1
    shift
    ;;
esac

if (( CODEX_STATUS_ONLY || CODEX_DOCTOR_ONLY )) && (( $# > 0 )); then
  if (( CODEX_STATUS_ONLY )); then
    printf 'Usage: cdx [--debug] status\n' >&2
  else
    printf 'Usage: cdx [--debug] doctor\n' >&2
  fi
  exit 1
fi

if [[ -n "${1-}" && "${1-}" != -* ]]; then
  if ! is_reserved_codex_command "${1-}"; then
    CODEX_PROFILE_CANDIDATE="$1"
    shift
  fi
fi

if (( ! IS_ROOT )) && (( CAN_SUDO == 0 )); then
  log_info "Non-root execution detected; skipping automatic Codex install/update (passwordless sudo required)."
fi
log_debug "starting | user=${CURRENT_USER} | is_root=${IS_ROOT} | can_sudo=${CAN_SUDO} | path=$PATH"

detect_linux_package_manager() {
  local tokens=()
  if [[ -r /etc/os-release ]]; then
    # shellcheck disable=SC1091
    . /etc/os-release
    if [[ -n "${ID:-}" ]]; then
      tokens+=("$ID")
    fi
    if [[ -n "${ID_LIKE:-}" ]]; then
      local like
      for like in $ID_LIKE; do
        tokens+=("$like")
      done
    fi
  fi
  local token
  for token in "${tokens[@]}"; do
    case "$token" in
      debian|ubuntu)
        if command -v apt-get >/dev/null 2>&1; then
          printf '%s' apt-get
          return 0
        fi
        ;;
      rhel|centos|fedora|almalinux|rocky|ol)
        if command -v dnf >/dev/null 2>&1; then
          printf '%s' dnf
          return 0
        fi
        if command -v yum >/dev/null 2>&1; then
          printf '%s' yum
          return 0
        fi
        ;;
      arch|manjaro|endeavouros)
        if command -v pacman >/dev/null 2>&1; then
          printf '%s' pacman
          return 0
        fi
        ;;
      opensuse*|sles|sled|suse)
        if command -v zypper >/dev/null 2>&1; then
          printf '%s' zypper
          return 0
        fi
        ;;
      alpine)
        if command -v apk >/dev/null 2>&1; then
          printf '%s' apk
          return 0
        fi
        ;;
    esac
  done
  if command -v apt-get >/dev/null 2>&1; then
    printf '%s' apt-get
    return 0
  fi
  if command -v dnf >/dev/null 2>&1; then
    printf '%s' dnf
    return 0
  fi
  if command -v yum >/dev/null 2>&1; then
    printf '%s' yum
    return 0
  fi
  if command -v pacman >/dev/null 2>&1; then
    printf '%s' pacman
    return 0
  fi
  if command -v zypper >/dev/null 2>&1; then
    printf '%s' zypper
    return 0
  fi
  if command -v apk >/dev/null 2>&1; then
    printf '%s' apk
    return 0
  fi
  return 1
}

with_sudo() {
  if (( EUID == 0 )); then
    "$@"
  elif command -v sudo >/dev/null 2>&1; then
    sudo "$@"
  else
    return 1
  fi
}

remove_path() {
  local path="$1"
  local label="$2"
  [[ -z "$path" || "$path" == "/" ]] && return 0
  if rm -rf "$path" 2>/dev/null; then
    log_info "Removed $label ($path)"
    return 0
  fi
  if with_sudo rm -rf "$path" 2>/dev/null; then
    log_info "Removed $label ($path) with sudo"
    return 0
  fi
  log_warn "Unable to remove $label ($path)"
  return 1
}

maybe_home() {
  local user="$1"
  local home=""
  if command -v getent >/dev/null 2>&1; then
    home="$(getent passwd "$user" | cut -d: -f6 2>/dev/null || true)"
  fi
  [[ -z "$home" ]] && home="/home/$user"
  printf '%s\n' "$home"
}

uninstall_api_deregister() {
  local base="${CODEX_SYNC_BASE_URL%/}"
  local key="$CODEX_SYNC_API_KEY"
  local cafile="$CODEX_SYNC_CA_FILE"
  if [[ -z "$base" || -z "$key" ]]; then
    log_warn "Skipping API deregistration (missing base URL or API key)"
    return
  fi
  local url="${base}/auth?force=1"
  local args=(-fsS -X DELETE -H "X-API-Key: ${key}")
  if [[ "$CODEX_FORCE_IPV4" == "1" ]]; then
    args+=("-4")
  fi
  [[ -n "$cafile" ]] && args+=(--cacert "$cafile")
  if curl "${args[@]}" "$url" >/dev/null 2>&1; then
    log_info "API deregistration succeeded"
  else
    log_warn "API deregistration failed (continuing cleanup)"
  fi
}

record_host_user_with_api() {
  load_sync_config
  local base="${CODEX_SYNC_BASE_URL%/}"
  local key="$CODEX_SYNC_API_KEY"
  local cafile="$CODEX_SYNC_CA_FILE"
  if [[ -z "$base" || -z "$key" ]]; then
    return 1
  fi
  local hostname="$LOCAL_HOSTNAME"
  [[ -z "$hostname" || "$hostname" == "unknown" ]] && hostname="$(hostname 2>/dev/null || echo unknown)"

  local payload
  if ! payload="$(USERNAME="$CURRENT_USER" HOSTNAME="$hostname" python3 - <<'PY' 2>/dev/null
import json, os, sys
user = os.environ.get("USERNAME", "").strip()
host = os.environ.get("HOSTNAME", "").strip()
print(json.dumps({"username": user, "hostname": host}, ensure_ascii=False))
PY
)"; then
    return 1
  fi

  local url="${base}/host/users"
  local args=(-fsS -X POST -H "X-API-Key: ${key}" -H "Content-Type: application/json" --data "$payload")
  if [[ "$CODEX_FORCE_IPV4" == "1" ]]; then
    args+=("-4")
  fi
  [[ -n "$cafile" ]] && args+=(--cacert "$cafile")
  local response=""
  if ! response="$(curl "${args[@]}" "$url" 2>/dev/null)"; then
    return 1
  fi

  local parsed_users=()
  local parsed_output=""
  if parsed_output="$(API_RESPONSE="$response" python3 - <<'PY' 2>/dev/null
import json, os
data = os.environ.get("API_RESPONSE", "")
parsed = json.loads(data)
users = parsed.get("data", {}).get("users")
if not isinstance(users, list):
    raise SystemExit(1)
seen = set()
for entry in users:
    username = None
    if isinstance(entry, dict):
        username = entry.get("username")
    elif isinstance(entry, str):
        username = entry
    if not username:
        continue
    username = str(username).strip()
    if not username or username in seen:
        continue
    seen.add(username)
    print(username)
PY
  )"; then
    while IFS= read -r line; do
      [[ -z "$line" ]] && continue
      parsed_users+=("$line")
    done <<< "$parsed_output"
  else
    parsed_users=()
  fi
  HOST_USERS_CACHE=("${parsed_users[@]-}")
  HOST_USERS_FETCHED=1
  return 0
}

persist_lane_preference_with_api() {
  load_sync_config
  local requested_lane="${1-}"
  local base="${CODEX_SYNC_BASE_URL%/}"
  local key="$CODEX_SYNC_API_KEY"
  local cafile="$CODEX_SYNC_CA_FILE"
  if [[ -z "$base" || -z "$key" ]]; then
    return 1
  fi
  if ! command -v python3 >/dev/null 2>&1; then
    return 1
  fi

  local parsed_output=""
  if ! parsed_output="$(CODEX_SYNC_BASE="$base" CODEX_SYNC_API_KEY="$key" CODEX_SYNC_CA_FILE="$cafile" CODEX_SYNC_LANE_REQUEST="$requested_lane" python3 - <<'PY' 2>/dev/null
import os
import sys

py_http_util = os.environ.get("CODEX_PY_HTTP_UTIL", "")
if py_http_util:
    exec(py_http_util, globals())
if "cdx_enable_force_ipv4" in globals():
    cdx_enable_force_ipv4()

base = (os.environ.get("CODEX_SYNC_BASE", "") or "").rstrip("/")
api_key = os.environ.get("CODEX_SYNC_API_KEY", "") or ""
cafile = os.environ.get("CODEX_SYNC_CA_FILE", "") or ""
lane_raw = (os.environ.get("CODEX_SYNC_LANE_REQUEST", "") or "").strip().lower()

if not base or not api_key:
    sys.exit(2)

lane = None
if lane_raw:
    if lane_raw not in ("normal", "spark"):
        print("error=invalid-lane")
        sys.exit(3)
    lane = lane_raw

payload = {"lane": lane, "reason": "cdx lane --persist"}
try:
    if "cdx_request_json" in globals():
        response = cdx_request_json(
            "POST",
            f"{base}/host/lane",
            api_key,
            cafile=cafile,
            payload=payload,
            allow_insecure_env="CODEX_SYNC_ALLOW_INSECURE",
        )
    else:
        raise RuntimeError("python-http-util-missing")
except Exception as exc:  # noqa: BLE001
    print(f"error={exc}")
    sys.exit(4)

data = response.get("data") if isinstance(response, dict) else {}
if not isinstance(data, dict):
    data = {}

pref = data.get("lane_preference")
effective = data.get("effective_lane")

if isinstance(pref, str):
    pref = pref.strip().lower()
else:
    pref = ""
if pref not in ("normal", "spark"):
    pref = ""
if pref:
    print(f"pref={pref}")
else:
    print("pref=")

if isinstance(effective, str):
    effective = effective.strip().lower()
else:
    effective = ""
if effective in ("normal", "spark"):
    print(f"effective={effective}")
PY
)"; then
    return 1
  fi

  local line
  local parsed_pref=""
  local parsed_effective=""
  while IFS= read -r line; do
    case "$line" in
      pref=*)
        parsed_pref="${line#pref=}"
        ;;
      effective=*)
        parsed_effective="${line#effective=}"
        ;;
    esac
  done <<< "$parsed_output"

  HOST_LANE_PREFERENCE="$parsed_pref"
  if [[ "$parsed_effective" == "normal" || "$parsed_effective" == "spark" ]]; then
    CODEX_EFFECTIVE_LANE="$parsed_effective"
  fi

  return 0
}

cmd_uninstall() {
  log_info "Starting Codex uninstall"
  load_sync_config
  record_host_user_with_api || true

  # Refuse partial multi-user uninstalls when we cannot escalate permissions.
  if (( EUID != 0 )) && (( CAN_SUDO == 0 )) && (( ${#HOST_USERS_CACHE[@]} > 0 )); then
    local other_users=()
    local seen_other=()
    local other existing skip
    for other in "${HOST_USERS_CACHE[@]}"; do
      [[ -z "$other" || "$other" == "$CURRENT_USER" ]] && continue
      skip=0
      for existing in "${seen_other[@]}"; do
        if [[ "$existing" == "$other" ]]; then
          skip=1
          break
        fi
      done
      (( skip )) && continue
      seen_other+=("$other")
      other_users+=("$other")
    done
    if (( ${#other_users[@]} > 0 )); then
      log_error "Uninstall refused: host has registered users besides ${CURRENT_USER} (${other_users[*]}), but root/sudo is unavailable."
      log_error "Rerun as root or with passwordless sudo so all registered users can be cleaned safely."
      exit 1
    fi
  fi

  uninstall_api_deregister

  # Legacy env/config files
  remove_path "/usr/local/etc/codex-sync.env" "sync env (system)"
  remove_path "/etc/codex-sync.env" "sync env (system-legacy)"
  remove_path "$HOME/.codex/sync.env" "sync env (user)"

  # Auth + state per user (from API fallback to current user)
  local users=()
  if (( ${#HOST_USERS_CACHE[@]} == 0 )); then
    users+=("$CURRENT_USER")
  else
    users+=("${HOST_USERS_CACHE[@]}")
  fi
  local ensured_current=0
  local u
  for u in "${users[@]}"; do
    [[ "$u" == "$CURRENT_USER" ]] && ensured_current=1 && break
  done
  (( ensured_current )) || users+=("$CURRENT_USER")

  local seen=()
  local home
  for u in "${users[@]}"; do
    local skip=0
    for existing in "${seen[@]}"; do
      [[ "$existing" == "$u" ]] && skip=1 && break
    done
    (( skip )) && continue
    seen+=("$u")
    home="$(maybe_home "$u")"
    [[ ! -d "$home" ]] && continue
    remove_path "$home/.codex/auth.json" "auth.json for $u"
    remove_path "$home/.codex" ".codex dir for $u"
  done

  # Binaries and install dirs
  remove_path "/usr/local/bin/cdx" "cdx binary"
  remove_path "$HOME/.local/bin/cdx" "cdx binary (user)"
  remove_path "/usr/local/bin/codex" "codex binary"
  remove_path "$HOME/.local/bin/codex" "codex binary (user)"
  remove_path "/opt/codex" "/opt/codex directory"

  # NPM global package (best effort)
  if command -v npm >/dev/null 2>&1; then
    if npm list -g codex-cli --depth=0 >/dev/null 2>&1; then
      if (( EUID == 0 )); then
        npm uninstall -g codex-cli >/dev/null 2>&1 || log_warn "npm uninstall codex-cli failed"
      else
        with_sudo npm uninstall -g codex-cli >/dev/null 2>&1 || npm uninstall -g codex-cli >/dev/null 2>&1 || log_warn "npm uninstall codex-cli failed"
      fi
      log_info "Removed npm codex-cli (if present)"
    fi
  fi

  log_info "Codex uninstall complete"
  exit 0
}
